  "footer.scrolltop": { en: "↑ Back to top", es: "↑ Volver arriba" },
  "footer.text": { en: "Part of <a href=\"https://quarcs-lab.github.io/metricsai/book/_book/index.html\"><strong>metricsAI</strong></a> · Chapter 03: The Sample Mean · by Carlos Mendez · <a href=\"https://github.com/quarcs-lab/metricsai\">GitHub</a>", es: "Parte de <a href=\"https://quarcs-lab.github.io/metricsai/book/_book/index.html\"><strong>metricsAI</strong></a> · Capítulo 03: La media muestral · por Carlos Mendez · <a href=\"https://github.com/quarcs-lab/metricsai\">GitHub</a>" },
