  "widget.clt.ctrl.n.label": { en: "Sample size (n)", es: "Tamaño de muestra (n)" },
  "widget.clt.ctrl.pop.label": { en: "Population Shape", es: "Forma de la población" },
  "widget.clt.ctrl.pop.opt.bernoulli": { en: "Bernoulli (p = 0.5)", es: "Bernoulli (p = 0.5)" },
